\draw[{Stealth}-{Stealth}] (-3.6,0) -- (3.6,0) node[right] {$x$};
\draw[{Stealth}-{Stealth}] (0,-3.6) -- (0,3.6) node[above] {$y$};
\draw[thick,{Stealth}-{Stealth}] (-0.34,-3.4) -- (1.02,3.4) node[above left] {$m_1$};
\draw[thick,{Stealth}-{Stealth}] (3.4,1.38) -- (-3.4,0.02) node[below left] {$m_2$};
\coordinate (P) at (0.5,0.8);
\coordinate (A) at (1.02,3.4);
\coordinate (B) at (3.4,1.38);
